+{"connection_id":"BC-381de7f24e98cf3a90b5","ref":"SBLGNT:Rev.6.17","status":"accepted","reason":"Gazabın büyük günü anlatısı ¶34'ün zaman ve karşı sonuç düzenine paraleldir.","paragraphs":[34],"evidence":["SBLGNT:Rev.6.17"],"annotations":["S001-INC-MTF-003"]}
