+{"connection_id":"BC-ab5c8f4363e785f3e5e9","ref":"WLC:Isa.12.1","status":"rejected","reason":"Geçmiş öfkenin yatışıp teselliye dönmesi vardır; ¶32'nin eşzamanlı nimet-gazap dağılımı değil, tek konuşurun zaman içi değişimidir.","paragraphs":[32],"evidence":["WLC:Isa.12.1"],"annotations":[]}
+{"connection_id":"BC-8eb91d6d5677070c45c7","ref":"WLC:Isa.12.1","status":"rejected","reason":"Öfkeden teselliye geçiş bir şükran sözüdür; ¶32'deki farklı grupların üstündeki iki sonuç ayrımı değildir.","paragraphs":[32],"evidence":["WLC:Isa.12.1"],"annotations":[]}
+{"connection_id":"BC-ea81f63bfdbba859119f","ref":"WLC:Isa.13.8","status":"rejected","reason":"Yüzlerin alev gibi görünmesi ilahî gün korkusuna bağlıdır; ¶33'ün öfkeli yüzü veya ¶34'ün iki karşı yüzü değildir.","paragraphs":[34],"evidence":["WLC:Isa.13.8"],"annotations":[]}
+{"connection_id":"BC-b76e359b4a9b1bb26fbd","ref":"WLC:Isa.13.9","status":"accepted","reason":"İbranice yom ile Arapça yevm kökteştir; gazapla gelen ilahî günü kaynak ayet açıkça adlandırır.","paragraphs":[34],"evidence":["WLC:Isa.13.9"],"annotations":["S001-TEV-SYD-003"]}
+{"connection_id":"BC-19dbd339dde5c9a97b68","ref":"WLC:Isa.2.3","status":"rejected","reason":"Ulusların yolları öğrenip birlikte yürümeleri yol-topluluk bağıdır; ¶36'nın nimet verilmiş belirli kişileri ve yüz sonuçları yoktur.","paragraphs":[36],"evidence":["WLC:Isa.2.3"],"annotations":[]}
+{"connection_id":"BC-6db8ac4c1b2dcb1884b4","ref":"WLC:Isa.25.8","status":"rejected","reason":"Bütün yüzlerden gözyaşının silinmesi güçlü öncül motifidir; ¶36'da kılavuzlukla beraber gözyaşını veren Vahiy 7:17 seçildi.","paragraphs":[36],"evidence":["WLC:Isa.25.8"],"annotations":[]}
+{"connection_id":"BC-ef5afea19d4d5dd7d807","ref":"WLC:Isa.29.22","status":"rejected","reason":"Yakup'un utanç ve solgun yüzünün kalkması tarihsel soyun kurtuluşudur; ¶36'daki iki son-gün grubunu birlikte göstermez.","paragraphs":[36],"evidence":["WLC:Isa.29.22"],"annotations":[]}
+{"connection_id":"BC-3f528b204db9700ab36a","ref":"WLC:Isa.30.21","status":"rejected","reason":"Ardından yürünecek yolu sesin göstermesi kılavuzluk motifidir; ¶36'nın yüz ve nimet verilmiş yoldaşlarıyla daha dolaylıdır.","paragraphs":[36],"evidence":["WLC:Isa.30.21"],"annotations":[]}
+{"connection_id":"BC-78b18cdded3ac63f18bb","ref":"WLC:Isa.35.10","status":"rejected","reason":"Kurtulanların Sevinç içinde Siyon'a birlikte dönüşü tarihsel restorasyon sahnesidir; ¶36'nın son-yargı yüz ayrımı yoktur.","paragraphs":[36],"evidence":["WLC:Isa.35.10"],"annotations":[]}
+{"connection_id":"BC-517e2c386cb6ba05edc4","ref":"WLC:Isa.35.8","status":"rejected","reason":"Kutsal yol ve sapmama güçlü yol paralelidir; ¶36'da nimet sözcüğüyle bağlanan Süleyman'ın Meselleri 3:17 daha dar seçildi.","paragraphs":[36],"evidence":["WLC:Isa.35.8"],"annotations":[]}
+{"connection_id":"BC-d833b36b2940c5b7e6d7","ref":"WLC:Isa.35.8","status":"rejected","reason":"Kutsal yolda sapmama olumlu rehberliktir; paragrafın yüz ve adlandırılmış nimet verilenler katmanını genişletmez.","paragraphs":[36],"evidence":["WLC:Isa.35.8"],"annotations":[]}
+{"connection_id":"BC-cc8c0b4606f04abe3114","ref":"WLC:Isa.42.16","status":"rejected","reason":"Körleri yolda yürütüp karanlığı ışığa dönüştürme Tanrı'nın kılavuzluğudur; ¶36'nın iki grubun son yüzünü anlatmaz.","paragraphs":[36],"evidence":["WLC:Isa.42.16"],"annotations":[]}
+{"connection_id":"BC-de573c7a62da142807ac","ref":"WLC:Isa.48.17","status":"rejected","reason":"Yararlı yolu öğreten Tanrı genel hidayet paralelidir; nimet/yüz/yoldaş üçlüsüne doğrudan sözcük bağı yoktur.","paragraphs":[36],"evidence":["WLC:Isa.48.17"],"annotations":[]}
+{"connection_id":"BC-28dcd5cc16582ab76dd6","ref":"WLC:Isa.48.17","status":"rejected","reason":"Tanrı'nın yürünecek yolda kılavuzluğu nettir; ¶36 için seçilen Meseller 3:17 hem yolu hem noam kökünü verir.","paragraphs":[36],"evidence":["WLC:Isa.48.17"],"annotations":[]}
+{"connection_id":"BC-24e80bd0aa0f12146db5","ref":"WLC:Isa.53.6","status":"rejected","reason":"Hepimizin sapması ve suçun kula yüklenmesi ayette bulunur; ¶35'teki buzağı olayının suç ve öfke yerleşimiyle doğrudan aynı olay değildir.","paragraphs":[35],"evidence":["WLC:Isa.53.6"],"annotations":[]}
+{"connection_id":"BC-a32d744aea49db92ea77","ref":"WLC:Isa.54.8","status":"rejected","reason":"Öfkeyle gizlenen yüz Tanrı'nınkidir ve sonra merhamet gelir; ¶33'ün değişen insan yüzüyle özne farklıdır.","paragraphs":[33],"evidence":["WLC:Isa.54.8"],"annotations":[]}
