{"connection_id":"BC-68a3450d4c2ac795c1e7","ref":"WLC:Exod.32.19","status":"accepted","reason":"Musa'nın gözle görülen putperestliğe öfkesi şerhin hatırlattığı olay örgüsüdür.","paragraphs":[35],"evidence":["WLC:Exod.32.19"],"annotations":["S001-TEV-PRL-002"]}
